const agentOutput = ($input.first().json.output || '').trim();

const opPatterns = [
  { type: 'upload',   re: /upload|creat|wrote|saved|added/i },
  { type: 'download', re: /download|retriev|read|fetch/i },
];
let operation = 'unknown';
for (const p of opPatterns) {
  if (p.re.test(agentOutput)) { operation = p.type; break; }
}

const webUrlMatch = agentOutput.match(/https?:\/\/[^\s"'<>]*sharepoint[^\s"'<>]*/i);
const webUrl = webUrlMatch ? webUrlMatch[0].replace(/[.,;)]+$/, '') : null;

// Only throw if the agent explicitly reports a tool-level failure — not for general error words in its own reasoning
const isToolError = /Upload failed|Download failed|error:\s+(siteUrl|folderPath|fileName|fileContent|401|403|404|500)/i.test(agentOutput);

if (isToolError) {
  return [{
    json: {
      success: false,
      operation,
      webUrl,
      error: agentOutput,
      agentMessage: agentOutput,
    }
  }];
}

return [{
  json: {
    success: true,
    operation,
    webUrl,
    agentMessage: agentOutput,
  }
}];
